/**
 * Generates a Storybook story next to every demo (src/components/<category>/<Name>/<Name>.demo.tsx) and page
 * (src/pages/<Name>/<Name>.page.tsx), so Storybook always lists the same components as the gallery.
 *   node scripts/generate/stories.mjs
 * Existing hand-written stories (e.g. Button.stories.tsx) are left alone. Generated files carry a "GENERATED" header and are
 * safe to delete and regenerate.
 */
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = new URL('../../src', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
const label = (s) => s.replace(/-/g, ' ').replace(/^./, (m) => m.toUpperCase());
let made = 0, kept = 0;

const write = (file, body) => {
  if (existsSync(file) && !readFileSync(file, 'utf8').startsWith('// GENERATED')) { kept++; return; }
  writeFileSync(file, body);
  made++;
};

// components
const comps = join(root, 'components');
for (const cat of readdirSync(comps)) {
  const catDir = join(comps, cat);
  if (cat.startsWith('_') || !statSync(catDir).isDirectory()) continue;
  for (const name of readdirSync(catDir)) {
    const dir = join(catDir, name);
    if (!statSync(dir).isDirectory() || !existsSync(join(dir, `${name}.demo.tsx`))) continue;
    write(
      join(dir, `${name}.stories.tsx`),
      `// GENERATED by scripts/generate/stories.mjs from ${name}.demo.tsx. Do not edit; run \`npm run stories:build\`.
import type { Meta, StoryObj } from '@storybook/react-vite';
import Demo from './${name}.demo';

const meta = { title: '${label(cat)}/${name}', component: Demo, parameters: { layout: 'padded' } } satisfies Meta<typeof Demo>;
export default meta;

/** Every variant, size and state the Figma file defines for ${name}. */
export const AllVariants: StoryObj<typeof meta> = {};
`,
    );
  }
}

// pages
const pages = join(root, 'pages');
for (const name of readdirSync(pages)) {
  const dir = join(pages, name);
  if (!statSync(dir).isDirectory() || !existsSync(join(dir, `${name}.page.tsx`))) continue;
  write(
    join(dir, `${name}.stories.tsx`),
    `// GENERATED by scripts/generate/stories.mjs from ${name}.page.tsx. Do not edit; run \`npm run stories:build\`.
import type { Meta, StoryObj } from '@storybook/react-vite';
import Page from './${name}.page';

const meta = { title: 'Pages/${name}', component: Page, parameters: { layout: 'fullscreen' } } satisfies Meta<typeof Page>;
export default meta;

/** A full page assembled only from design-system components. */
export const Page_: StoryObj<typeof meta> = { name: 'Page' };
`,
  );
}
console.log(`stories written: ${made}, hand-written kept: ${kept}`);
